@Entity
public class Product {
    @Id @GeneratedValue
    private Long id;

    @Version
    private Long version;

    private String name;
}

// Service layer handling
@Transactional
public void updateProduct(Long id, String newName) {
    try {
        Product p = repository.findById(id).orElseThrow();
        p.setName(newName);
        repository.save(p);
    } catch (OptimisticLockException e) {
        // Logic to handle conflict: retry, notify user, or log
        throw new ConflictException("Data was updated by another user");
    }
}
